import sys


def write(leaf,root,css,description,fixtures):
 css=css.replace('padding:1%','padding:calc(var(--gap-sm)/2)')
 if leaf in ['cycle','hub']:
  css=css.replace('gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink);--od-radial-n','column-gap:0;row-gap:var(--gap-sm);min-width:0;min-height:0;color:var(--ink);--od-radial-n')
